
import base64

def __decode_b64(s):
    return base64.b64decode(s).decode('utf-8')

def __xor_decrypt(data, key):
    result = bytearray()
    key_bytes = key.encode('utf-8')
    for i in range(len(data)):
        result.append(data[i] ^ key_bytes[i % len(key_bytes)])
    return bytes(result)

__ENCRYPTED_CODE = '''

'''

__KEY = 'jh_efat'

try:
    __decoded_b64 = base64.b64decode(__ENCRYPTED_CODE)
    __decrypted = __xor_decrypt(__decoded_b64, __KEY)
    __final_code = __decrypted.decode('utf-8')
    exec(__final_code)
except Exception as e:
    print(f'Execution error: {e}')

